def script(level,request,context,obstacle,alternative,reason):
    if level=='A1':return f'Persona: {request} {context}|Interlocutor: {obstacle}|Persona: ¿Qué podemos hacer?|Interlocutor: {alternative}|Persona: {reason}'
    if level=='A2':return f'Persona: {request} {context} Ayer intenté resolver esta situación.|Interlocutor: Entiendo. {obstacle}|Persona: ¿Hay otra opción para esta semana?|Interlocutor: {alternative}|Persona: Me parece bien. {reason}|Interlocutor: Vamos a confirmarlo antes de terminar.'
    if level=='B1':return f'Persona: Me gustaría explicar lo que necesito. {request} {context}|Interlocutor: Antes de decidir, debemos tener en cuenta una dificultad. {obstacle}|Persona: ¿Podríamos buscar una alternativa en lugar de cancelar el plan?|Interlocutor: {alternative}|Persona: Esa opción me resulta útil. {reason}|Interlocutor: Entonces confirmemos los detalles para evitar un malentendido.'
    if level=='B2':return f'Persona: {request} {context} Preferiría valorar varias posibilidades antes de decidir.|Interlocutor: La dificultad es la siguiente. {obstacle} No obstante, hay otra vía. {alternative}|Persona: Podría aceptar esa propuesta siempre que confirmemos sus condiciones.|Interlocutor: De acuerdo. Su ventaja es esta. {reason}|Persona: Conviene dejar claro qué hemos acordado y qué queda pendiente.|Interlocutor: Lo confirmaremos por escrito antes de darlo por definitivo.'
    if level=='C1':return f'Persona: Mi petición es concreta. {request} {context} Sin embargo, no quisiera confundir una preferencia con una condición imprescindible.|Interlocutor: Hay una limitación que debemos explicitar. {obstacle} La alternativa que proponemos es esta. {alternative}|Persona: ¿Qué justificación respalda esa opción?|Interlocutor: {reason} Eso explica su utilidad, aunque no garantiza que todas las demás circunstancias sean favorables.|Persona: Acepto examinarla, siempre que distingamos lo confirmado de lo que todavía depende de una comprobación.|Interlocutor: Documentaremos los límites del acuerdo, sin presentar una propuesta provisional como una solución definitiva.'
    return f'Persona: {request} {context} Mi interés en una solución no debería interpretarse como aceptación anticipada de cualquier condición.|Interlocutor: Comprendo el matiz. {obstacle} Cabe explorar una alternativa. {alternative}|Persona: ¿La formulación expresa un compromiso firme o una posibilidad aún por confirmar?|Interlocutor: Por ahora, una posibilidad. Su fundamento práctico es este. {reason} Sería impropio dar por resueltas cuestiones que aún no hemos contrastado.|Persona: Entonces propongo conservar esa distinción al comunicar el acuerdo, para no generar expectativas que excedan lo efectivamente establecido.|Interlocutor: Así lo haremos. Avanzar en la conversación no implica borrar las reservas, sino hacer explícito qué alcance atribuimos a cada compromiso.'

def expand(existing):
    counts=Counter(l['level'] for l in existing);result=[]
    for level in LEVELS:
        for slug,title,theme,request,context,obstacle,alternative,reason,terms in CASES:
            if counts[level]>=25:break
            wrong=[case for case in CASES if case[0]!=slug][:2]
            quiz=[('¿Qué necesita la persona en esta situación?',request,wrong[0][3],wrong[1][3],'La petición aparece explícitamente al inicio del audio.'),('¿Qué dificultad se menciona?',obstacle,wrong[0][5],wrong[1][5],'Esta es la limitación que explica el interlocutor.')]
            if level in ('A1','A2','B1'):quiz.append(('¿Qué alternativa se propone?',alternative,wrong[0][6],wrong[1][6],'La propuesta responde a la dificultad de esta situación.'))
            elif level=='B2':quiz.append(('¿Qué se hará antes de dar el acuerdo por definitivo?','Confirmar sus condiciones por escrito','Suponer que todo está resuelto','Cancelar sin hablar de alternativas','La última intervención propone confirmar el acuerdo por escrito.'))
            else:quiz.append(('¿Cómo se presenta la alternativa?','Como una propuesta cuyo alcance y límites deben aclararse','Como una garantía absoluta sin condiciones','Como un hecho que ya no necesita comprobación','El interlocutor distingue la propuesta de una solución garantizada.'))
            first={'A1':'Escribe entre dos y cuatro frases para expresar tu necesidad y aceptar una opción.','A2':'Escribe un diálogo de cuatro turnos e incluye una pregunta cortés.','B1':'Relata la situación, explica el motivo de tu decisión y propone otra posibilidad.','B2':'Redacta una objeción cortés y negocia una condición usando una concesión.','C1':'Expón una propuesta matizada y distingue los hechos comprobados de tus supuestos.','C2':'Reformula la conversación en otro registro sin alterar el alcance de los compromisos.'}[level]
            written=[f'{title}: {first}',f'Aplica la situación a un contexto propio o inventado. Explica por qué la alternativa propuesta puede ser útil: «{reason}».' if level!='A1' else 'Escribe una pregunta sencilla para confirmar un detalle de esta situación.']
            lesson=make(f'itinerary-{level.lower()}-{slug}',title,level,theme,script(level,request,context,obstacle,alternative,reason),[term.split('~') for term in terms.split(';')],quiz,written)
            lesson['minutes']={'A1':10,'A2':12,'B1':15,'B2':18,'C1':20,'C2':22}[level]
            result.append(lesson);counts[level]+=1
    assert all(counts[l]>=25 for l in LEVELS)
    return result
